const examRhetoric=[{"title":"الدورة الثانية 2022 — تشبيه بليغ","level":"بكالوريا","sentence":"الصورة الواردة في السلم: «جنّة العلم».","word":"ما نوع الصورة البيانية في «جنّة العلم»؟","answer":"تشبيه بليغ إضافي؛ المشبّه العلم، والمشبّه به الجنّة، وحُذفت أداة التشبيه ووجه الشبه.","why":"سلم التصحيح يفصل المشبّه والمشبّه به وحذف الأداة ووجه الشبه وتسمية الصورة.","source":"سلم الفرع العلمي، الدورة الثانية 2022، PDF ص 61"},{"title":"الدورة الثانية 2022 — تحويل الأسلوب","level":"بكالوريا","sentence":"«شيّدوا المدارسَ»","word":"حوّل أسلوب الأمر إلى أسلوب خبري.","answer":"شيّدَ الناسُ المدارسَ. ويمكن القول: الناسُ يشيّدون المدارسَ.","why":"سلم التصحيح يقبل فعلاً ماضياً أو مضارعاً من «شاد» وصيغاً خبرية مناسبة؛ الجملة هنا مقتطف تعليمي.","source":"سلم الفرع العلمي، الدورة الثانية 2022، PDF ص 61"},{"title":"الدورة الأولى 2022 — تشبيه بليغ إضافي","level":"بكالوريا","sentence":"الصورة الواردة في السلم: «جنّات الهوى».","word":"ما نوع الصورة البيانية في «جنّات الهوى»؟","answer":"تشبيه بليغ إضافي؛ المشبّه الهوى والمشبّه به الجنّات، وحُذفت أداة التشبيه ووجه الشبه.","why":"ورد في السلم تحليل عناصر التشبيه وتسميته، مع توضيح أثر الصورة في المعنى.","source":"سلم الفرع العلمي، الدورة الأولى 2022، PDF ص 51"}];
const examComprehension=[{"title":"الدورة الثانية 2022 — أثر العلم في الحياة","level":"بكالوريا","sentence":"تدريب فهم مستند إلى عناصر الإجابة في السلم.","word":"اذكر أثرين لطلاب العلم في حياة المجتمع.","answer":"الإسهام في إصلاح شؤون الحياة، وإقامة العدل أو إنصاف المظلوم.","why":"السلم يذكر إصلاح الحياة وإقامة العدل أو الفصل بين الظالم والمظلوم. السؤال هنا من صياغة المنصة.","source":"سلم الفرع العلمي، الدورة الثانية 2022، PDF ص 59"},{"title":"الدورة الثانية 2022 — الدعوة إلى المدارس","level":"بكالوريا","sentence":"تدريب فهم مستند إلى عناصر الإجابة في السلم.","word":"إلى ماذا دعا الشاعر في موضوع العلم؟","answer":"دعا إلى بناء المدارس أو الاهتمام بها وبناء دور العلم.","why":"وردت هذه المعاني في إجابة السؤال الأول في السلم. السؤال معاد الصياغة.","source":"سلم الفرع العلمي، الدورة الثانية 2022، PDF ص 59"},{"title":"الدورة الأولى 2022 — الارتباط بالوطن","level":"بكالوريا","sentence":"تدريب فهم مستند إلى عناصر الإجابة في السلم.","word":"كيف صوّر الشاعر عمق ارتباطه بوطنه؟","answer":"صوّر ارتباطه بالوطن كارتباط الروح بالجسد، حتى إن البعد عنه يشبه جسداً بلا روح.","why":"تقبل الإجابات الموافقة للمعنى في سلم التصحيح؛ صياغة السؤال تعليمية.","source":"سلم الفرع العلمي، الدورة الأولى 2022، PDF ص 50"},{"title":"الدورة الأولى 2022 — قيمة إنسانية","level":"بكالوريا","sentence":"تدريب فهم مستند إلى عناصر الإجابة في السلم.","word":"استخلص قيمة إنسانية من حديث الشاعر عن الوطن.","answer":"حب الوطن والوفاء له، أو التعلّق به ورفض البعد عنه.","why":"هذه قيم مذكورة في سلم التصحيح؛ لا يتوفر النص الشعري الكامل هنا.","source":"سلم الفرع العلمي، الدورة الأولى 2022، PDF ص 50"}];
