function questionPrompt(q){
 const w=q.word||"",title=q.title||"";if(q.bookPage)return w;
 if(/^(ما |لماذا|رتّب|حوّل|أكّد|علّل|كيف |إلى ماذا|اذكر|استخلص|هات |تغنّى)/.test(w))return w;
 if(/جملة «/.test(w))return "بيّن المحل الإعرابي لـ"+w+" في السياق المعروض.";
 if(/اسم فاعل|مصدر|الألف|إعلال|مشتق|معجم/.test(title))return "أجب عن السؤال الصرفي أو الإملائي: «"+w+"»";
 if(/تشبيه|بلاغة/.test(title))return "حلّل الصورة البيانية: «"+w+"»";
 return "أعرب الكلمة الآتية في الجملة المعروضة: «"+w+"»";
}
