$('arabicEssayTopic').innerHTML=(level()==='تاسع'?topics:[...examEssayTopics.map(x=>x.title),...advancedTopics]).map(t=>'<option>'+escape(t)+'</option>').join('');
function essayPlan(){
 const title=$('arabicCustomTopic').value.trim()||$('arabicEssayTopic').value;
 const official=examEssayTopics.find(x=>x.title===title);
 if(official){$('arabicEssayOutline').innerHTML='<strong>تدريب مبني على عناصر سلم التصحيح:</strong> '+escape(official.source)+'<ol><li>مقدمة مرتبطة بالموضوع.</li>'+official.ideas.map(i=>'<li>'+escape(i)+' مع شرح وأمثلة مناسبة.</li>').join('')+'<li>خاتمة مناسبة.</li></ol>';return;}
 const normalized=title.replace(/[أإآ]/g,'ا');
 let ideas;
 if(/علم|عمل|نهض|تعليم/.test(normalized))ideas=['أهمية العلم في اكتساب المعرفة وتطوير مهارات الإنسان','قيمة العمل والإتقان في تحويل المعرفة إلى إنجازات','أمثلة واقعية من الطب والهندسة والزراعة ودور الفرد في تقدم المجتمع'];
 else if(/بيئ|تلوث|طبيع/.test(normalized))ideas=['أهمية البيئة السليمة للإنسان والكائنات الحية','أسباب التلوث وآثاره في الصحة والطبيعة','خطوات عملية للحد من التلوث ودور المدرسة والأسرة'];
 else if(/شباب|وطن/.test(normalized))ideas=['قدرات الشباب وأهمية تأهيلهم بالتعليم','مساهمتهم في العمل التطوعي والمبادرات المجتمعية','دورهم في تطوير الوطن وتجاوز التحديات'];
 else if(/قراء|كتاب|ثقاف/.test(normalized))ideas=['دور القراءة في اكتساب المعرفة وتنمية التفكير','أثر الكتب في اللغة والخيال وتوسيع الآفاق','طرق بناء عادة القراءة لدى الطلاب'];
 else if(/تكنولوج|تقني|تواصل|انترنت/.test(normalized))ideas=['الفوائد التعليمية والاجتماعية للتقنيات الحديثة','التحديات مثل إضاعة الوقت وانتشار المعلومات غير الدقيقة','كيفية الاستخدام المسؤول والمتوازن للتكنولوجيا'];
 else if(/حري|مسؤولي/.test(normalized))ideas=['معنى الحرية وعلاقتها باحترام حقوق الآخرين','كيف ترافق الحرية مسؤولية الفرد عن اختياراته','أمثلة من المدرسة والمجتمع على الموازنة بين الحرية والواجب'];
 else if(/هجر|اغتراب|انتماء/.test(normalized))ideas=['دوافع الهجرة أو الاغتراب وآثارها في الفرد','مشاعر الانتماء والحنين إلى الوطن في التجربة الإنسانية','طرق الحفاظ على الهوية والروابط الثقافية'];
 else if(/ادب|شعر|فن|ثقاف/.test(normalized))ideas=['أثر الأدب والفن في التعبير عن قضايا الإنسان','دورهما في تنمية الذوق والقيم والوعي','أمثلة على تأثير النصوص الأدبية في المجتمع'];
 else if(/وقت|تنظيم/.test(normalized))ideas=['قيمة الوقت في الدراسة والحياة اليومية','نتائج إهدار الوقت وتأجيل المهام','خطوات تنظيم اليوم وتحديد الأولويات'];
 else if(/تعاون|تكافل/.test(normalized))ideas=['معنى التعاون وأثره في العلاقات الإنسانية','أمثلة للتكافل في الأسرة والمدرسة والمجتمع','كيف يعزز التعاون مواجهة الصعوبات'];
 else ideas=['تعريف القضية الأساسية التي يطرحها الموضوع','عرض الأسباب والآثار مع أمثلة واقعية مرتبطة بالعنوان','مناقشة الحلول أو المسؤوليات والنتائج'];
 $('arabicEssayOutline').innerHTML='<strong>عنوان الموضوع:</strong> '+escape(title)+'<ol><li><strong>المقدمة:</strong> مهّد للموضوع وبيّن أهميته من دون الخروج عن العنوان.</li>'+ideas.map((idea,i)=>'<li><strong>فقرة العرض '+(i+1)+':</strong> '+escape(idea)+'.</li>').join('')+'<li><strong>الخاتمة:</strong> لخّص النتائج وقدّم موقفاً أو توصية مرتبطة بالموضوع.</li></ol><p>هذا مخطط إرشادي من إعداد المنصة وليس حلاً رسمياً من الكتاب.</p>';
}
